-- Every id is generated by its table's identity counter, and no code sets one by hand. A counter
-- that falls behind the rows already in its table (rows copied or restored with their ids) hands
-- out an id that is taken: creating a partner failed on locations_pkey this way. This moves each
-- counter in the schema to at least the highest id in use. It only ever moves a counter forward.
do $$
declare
  r   record;
  seq text;
  top bigint;
begin
  for r in
    select table_name, column_name from information_schema.columns
    where table_schema = current_schema() and is_identity = 'YES'
  loop
    seq := pg_get_serial_sequence(format('%I.%I', current_schema(), r.table_name), r.column_name);
    execute format('select max(%I) from %I.%I', r.column_name, current_schema(), r.table_name) into top;
    if top is not null then
      execute format('select setval(%L, greatest(%s, (select last_value from %s)))', seq, top, seq);
    end if;
  end loop;
end $$;
